INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Definition einer Methode in einer Klasse entscheidend?', 2, '[{"text": "Rückgabewert", "correct": true, "because": "Bestimmt, was die Methode liefert"}, {"text": "Farbe des Codes", "correct": false, "because": "Kein Einfluss auf Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist eine Methode ohne Parameter in einer Klasse möglich?', 1, '[{"text": "Ja", "correct": true, "because": "Parameter sind optional"}, {"text": "Nein", "correct": false, "because": "Nicht zwingend nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind für die Definition einer Methode wichtig?', 5, '[{"text": "Name", "correct": true, "because": "Identifiziert die Methode"}, {"text": "Rückgabetyp", "correct": true, "because": "Definiert Ausgabe"}, {"text": "Schriftart im Editor", "correct": false, "because": "Kein Einfluss"}, {"text": "Parameter", "correct": true, "because": "Beeinflusst Eingabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen über Methoden richtig? a) Methoden müssen immer etwas zurückgeben. b) Methoden können das Verhalten eines Objekts ändern.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Rückgabe optional"}, {"text": "Nur b) stimmt", "correct": true, "because": "Methoden ändern Zustand"}, {"text": "Beides stimmt", "correct": false, "because": "Aussage a) ist falsch"}, {"text": "Beides falsch", "correct": false, "because": "Aussage b) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du bei der Definition einer Methode ignorieren?', 2, '[{"text": "Sichtbarkeit (z.B. public)", "correct": false, "because": "Wichtig für Zugriff"}, {"text": "Codeformatierung", "correct": true, "because": "Nur Lesbarkeit, keine Funktion"}, {"text": "Parameterliste", "correct": false, "because": "Definiert Eingaben"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Definition einer Methode in einer Klasse entscheidend?', 2, '[{"text": "Rückgabewert", "correct": true, "because": "Bestimmt Ergebnis der Methode"}, {"text": "Farbe des Codes", "correct": false, "because": "Kein Einfluss auf Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist eine Methode ohne Parameter in der Objektorientierung möglich?', 1, '[{"text": "Ja", "correct": true, "because": "Parameter sind optional"}, {"text": "Nein", "correct": false, "because": "Nicht zwingend nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind für eine Methode wichtig?', 5, '[{"text": "Rückgabewert", "correct": true, "because": "Definiert Ausgabe"}, {"text": "Parameter", "correct": true, "because": "Eingabewerte beeinflussen Verhalten"}, {"text": "Schriftart im Editor", "correct": false, "because": "Kein Einfluss"}, {"text": "Sichtbarkeit (z.B. public)", "correct": true, "because": "Bestimmt Zugriff"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen über Methoden richtig? a) Methoden definieren das Verhalten einer Klasse. b) Jede Methode muss einen Rückgabewert haben.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Rückgabewert optional"}, {"text": "Beides stimmt", "correct": false, "because": "Void-Methoden existieren"}, {"text": "Nur b) stimmt", "correct": false, "because": "Verhalten ist Kern"}, {"text": "Beides falsch", "correct": false, "because": "Aussage a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du bei der Definition einer Methode ignorieren?', 2, '[{"text": "Parameterliste", "correct": false, "because": "Beeinflusst Funktionalität"}, {"text": "Codeformatierung", "correct": true, "because": "Ästhetik, kein Einfluss"}, {"text": "Sichtbarkeit", "correct": false, "because": "Wichtig für Zugriff"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
